<?php
namespace App\Http\Controllers\Api;
use App\Http\Controllers\Controller; use App\Models\Student; use App\Models\ActivityLog; use Illuminate\Http\Request; use Illuminate\Support\Str;
class StudentController extends Controller {
 public function index(Request $r){$q=Student::query();if($term=$r->string('search')->toString())$q->where(fn($x)=>$x->where('first_name','like',"%$term%")->orWhere('last_name','like',"%$term%")->orWhere('email','like',"%$term%")->orWhere('student_number','like',"%$term%"));if($r->filled('status')&&$r->status!=='All')$q->where('status',$r->status);if($r->filled('course')&&$r->course!=='All')$q->where('course',$r->course);match($r->query('sort','Newest')){'Name A–Z'=>$q->orderBy('first_name')->orderBy('last_name'),'GPA high'=>$q->orderByDesc('gpa'),default=>$q->orderByDesc('created_at')};return $q->paginate(min(max((int)$r->query('per_page',6),1),100));}
 public function show(Student $student){return $student;}
 private function rules(?int $id=null):array{return ['first_name'=>'required|string|max:100','last_name'=>'required|string|max:100','email'=>'required|email|max:190|unique:students,email'.($id?','.$id:''),'phone'=>'required|string|max:40','course'=>'required|string|max:120','year'=>'required|string|max:40','status'=>'required|in:Active,Inactive,On leave','gpa'=>'nullable|numeric|min:0|max:4','dob'=>'nullable|date','gender'=>'nullable|string|max:40','address'=>'nullable|string|max:2000','guardian'=>'nullable|string|max:160','guardian_phone'=>'nullable|string|max:40'];}
 public function store(Request $r){$d=$r->validate($this->rules());$s=Student::create([...$d,'student_number'=>$this->nextNumber(),'joined'=>now()->toDateString()]);ActivityLog::create(['admin_id'=>$r->user()->id,'action'=>'New student enrolled','detail'=>$s->first_name.' '.$s->last_name.' was added to '.$s->course,'kind'=>'add','metadata'=>['student_id'=>$s->id]]);return response()->json($s,201);}
 public function update(Request $r,Student $student){$d=$r->validate($this->rules($student->id));$student->update($d);ActivityLog::create(['admin_id'=>$r->user()->id,'action'=>'Student record updated','detail'=>$student->first_name.' '.$student->last_name.'’s profile was updated','kind'=>'edit','metadata'=>['student_id'=>$student->id]]);return $student->fresh();}
 public function destroy(Request $r,Student $student){$name=$student->first_name.' '.$student->last_name;$id=$student->id;$student->delete();ActivityLog::create(['admin_id'=>$r->user()->id,'action'=>'Student record deleted','detail'=>$name.' was removed from the directory','kind'=>'delete','metadata'=>['student_id'=>$id]]);return response()->noContent();}
 private function nextNumber():string{$latest=Student::query()->orderByDesc('id')->value('student_number');$sequence=$latest?(int)substr($latest,strrpos($latest,'-')+1):1000;return 'STU-'.now()->year.'-'.str_pad((string)($sequence+1),4,'0',STR_PAD_LEFT);}
}
